"""The ``pennywise`` command-line interface."""

import argparse
import csv
import json
import os
import sys
from typing import List, Optional

from . import ledger
from .ledger import Entry, ParseError

EXIT_OK = 0
EXIT_LEDGER = 1  # a mistake in the ledger, or in the entry given to ``add``
EXIT_USAGE = 2  # unreadable file or bad command line

PROG = "pennywise"


class _Failure(Exception):
    def __init__(self, status: int, message: str):
        super().__init__(message)
        self.status = status
        self.message = message


def _date_arg(text: str):
    try:
        return ledger.parse_date(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(str(exc)) from None


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog=PROG, description="See where the money in a plain-text ledger went."
    )
    sub = parser.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True

    def ledger_file(p):
        p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")

    p = sub.add_parser("balance", help="print the total of all entries")
    ledger_file(p)
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("summary", help="print totals per category or month")
    ledger_file(p)
    p.add_argument("--by", choices=["category", "month"], default="category",
                   help="group by category (default) or month")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("list", help="print entries, oldest first")
    ledger_file(p)
    p.add_argument("--category", metavar="C", help="only this category")
    p.add_argument("--since", metavar="DATE", type=_date_arg,
                   help="only entries on or after DATE (YYYY-MM-DD)")
    p.add_argument("--until", metavar="DATE", type=_date_arg,
                   help="only entries on or before DATE (YYYY-MM-DD)")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("add", help="append an entry to the ledger")
    p.add_argument("file", metavar="FILE", help="ledger file (created if missing)")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")

    p = sub.add_parser("export", help="print entries as CSV")
    ledger_file(p)
    p.add_argument("--format", choices=["csv"], default="csv",
                   help="output format (default: csv)")
    return parser


def _read_ledger(path: str) -> List[Entry]:
    try:
        if path == "-":
            data = sys.stdin.buffer.read() if hasattr(sys.stdin, "buffer") else None
            text = data.decode("utf-8-sig") if data is not None else sys.stdin.read()
        else:
            with open(path, "r", encoding="utf-8-sig", newline="") as f:
                text = f.read()
    except (OSError, UnicodeDecodeError) as exc:
        name = "standard input" if path == "-" else path
        raise _Failure(EXIT_USAGE, f"cannot read {name}: {_describe(exc)}") from None
    try:
        return ledger.parse(text)
    except ParseError as exc:
        name = "<stdin>" if path == "-" else path
        raise _Failure(EXIT_LEDGER, f"{name}: {exc}") from None


def _describe(exc: Exception) -> str:
    if isinstance(exc, OSError) and exc.strerror:
        return exc.strerror
    return str(exc)


def _chronological(entries: List[Entry]) -> List[Entry]:
    return sorted(entries, key=lambda e: e.date)  # sorted() is stable


def _entry_dict(e: Entry) -> dict:
    return {
        "date": e.date.isoformat(),
        "category": e.category,
        "amount": ledger.format_amount(e.amount),
        "note": e.note,
    }


def _cmd_balance(args) -> List[str]:
    total = ledger.format_amount(ledger.balance(_read_ledger(args.file)))
    return [json.dumps({"balance": total})] if args.json else [total]


def _cmd_summary(args) -> List[str]:
    entries = _read_ledger(args.file)
    group = ledger.by_month if args.by == "month" else ledger.by_category
    totals = {k: ledger.format_amount(v) for k, v in sorted(group(entries).items())}
    if args.json:
        return [json.dumps(totals)]
    return [f"{name}  {amount}" for name, amount in totals.items()]


def _cmd_list(args) -> List[str]:
    entries = ledger.filter_entries(
        _read_ledger(args.file), category=args.category,
        since=args.since, until=args.until,
    )
    entries = _chronological(entries)
    if args.json:
        return [json.dumps([_entry_dict(e) for e in entries])]
    return [ledger.format_entry(e) for e in entries]


def _cmd_export(args) -> List[str]:
    entries = _chronological(_read_ledger(args.file))

    class _Lines(list):
        def write(self, s):
            self.append(s)

    out = _Lines()
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in entries:
        d = _entry_dict(e)
        writer.writerow([d["date"], d["category"], d["amount"], d["note"]])
    return ["".join(out).rstrip("\n")]


def _cmd_add(args) -> List[str]:
    fields = [args.date, args.category, args.amount]
    shown = " ".join(fields + ([args.note] if args.note else []))
    if any(not f or any(c.isspace() for c in f) for f in fields):
        raise _Failure(EXIT_LEDGER,
                       f"invalid entry {shown!r}: DATE, CATEGORY and AMOUNT "
                       "must each be a single word")
    if any(c in args.note for c in "\r\n\x0b\x0c\x1c\x1d\x1e\x85  "):
        raise _Failure(EXIT_LEDGER, f"invalid entry {shown!r}: the note must be on one line")
    try:
        entry = ledger.parse_line(" ".join(fields + [args.note]))
    except ParseError as exc:
        raise _Failure(EXIT_LEDGER, f"invalid entry {shown!r}: {exc.reason}") from None
    if entry is None:  # e.g. a "date" beginning with '#'
        raise _Failure(EXIT_LEDGER, f"invalid entry {shown!r}")
    line = ledger.format_entry(entry)

    path = args.file
    try:
        prefix = ""
        if os.path.exists(path):
            with open(path, "rb") as f:
                size = f.seek(0, os.SEEK_END)
                if size:
                    f.seek(-1, os.SEEK_END)
                    if f.read(1) not in (b"\n", b"\r"):
                        prefix = "\n"
        with open(path, "a", encoding="utf-8", newline="") as f:
            f.write(prefix + line + "\n")
    except OSError as exc:
        raise _Failure(EXIT_USAGE, f"cannot write {path}: {_describe(exc)}") from None
    return [line]


_COMMANDS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "export": _cmd_export,
    "add": _cmd_add,
}


def main(argv: Optional[List[str]] = None) -> int:
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:  # argparse: --help exits 0, errors exit 2
        return exc.code if isinstance(exc.code, int) else EXIT_USAGE
    try:
        lines = _COMMANDS[args.command](args)
    except _Failure as exc:
        print(f"{PROG}: error: {exc.message}", file=sys.stderr)
        return exc.status
    try:
        for line in lines:
            print(line)
        sys.stdout.flush()
    except BrokenPipeError:
        # The reader went away (e.g. piped into `head`); don't make a fuss.
        try:
            devnull = os.open(os.devnull, os.O_WRONLY)
            os.dup2(devnull, sys.stdout.fileno())
        except (OSError, ValueError, AttributeError):
            pass
    return EXIT_OK


if __name__ == "__main__":
    sys.exit(main())
